function MilestoneCounter() {
  const [count,setCount]=useState(0);
  const counterRef=useRef<HTMLDivElement>(null);
  const started=useRef(false);
  useEffect(()=>{
    const node=counterRef.current;
    if(!node)return;
    const start=()=>{
      if(started.current)return;
      started.current=true;
      const target=10_000_000;
      if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){setCount(target);return;}
      const startTime=performance.now();
      const duration=1900;
      const tick=(now:number)=>{
        const progress=Math.min((now-startTime)/duration,1);
        const eased=1-Math.pow(1-progress,3);
        setCount(Math.max(1,Math.floor(target*eased)));
        if(progress<1)window.requestAnimationFrame(tick);
      };
      window.requestAnimationFrame(tick);
    };
    if(!('IntersectionObserver' in window)){start();return;}
    const observer=new IntersectionObserver(entries=>{
      if(entries.some(entry=>entry.isIntersecting)){start();observer.disconnect();}
    },{threshold:0.35});
    observer.observe(node);
    return()=>observer.disconnect();
  },[]);
  const shown=count>=10_000_000?'10M':count>=1_000_000?`${(count/1_000_000).toFixed(1)}M`:count.toLocaleString();
  return <div ref={counterRef} className="display text-5xl font-extrabold tracking-tight text-primary sm:text-6xl" aria-label="10,000,000 illustrative demo milestone, not verified users" data-testid="counter-demo-milestone">{shown}</div>;
}
